/// <summary>
/// UI Builder for Update slot area batch job
/// </summary>
public class METUpdateSlotAreaUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField threadCountField, warehouseField, noOfRecordsField;

}

Method.Source:
/// <summary>
/// Post build method
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    threadCountField = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METUpdateSlotAreaContract, parmThreadCount));
    threadCountField.value(1);

    warehouseField = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METUpdateSlotAreaContract, parmInventLocationId));

    noOfRecordsField = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METUpdateSlotAreaContract, parmMETNoOfRecords));
    noOfRecordsField.allowEdit(false);

    warehouseField.registerOverrideMethod( methodStr(FormStringControl, modified),
                                            methodStr(METUpdateSlotAreaUIBuilder, warehouseModified),
                                            this);

    METUpdateSlotAreaContract contract = this.dataContractObject() as METUpdateSlotAreaContract;

    if(contract.parmInventLocationId())
    {
        this.populateNoOfRecords(contract.parmInventLocationId());
    }

}

/// <summary>
/// Warehouse modified
/// </summary>
/// <param name = "_warehouse">FormStringControl</param>
/// <returns>boolean</returns>
public boolean warehouseModified(FormStringControl _warehouse)
{        
    this.populateNoOfRecords(_warehouse.valueStr());       

    return _warehouse.modified();
}

/// <summary>
/// Populate no of records
/// </summary>
/// <param name = "_warehouse">InventLocationId</param>
public void populateNoOfRecords(InventLocationId _warehouse)
{
    METReqItemTable metReqItemTable;
    ReqItemTable reqItemTable;
    InventDim inventDim;
    const int oneThousand = 1000; 
    const int twelve = 12;
    const int two = 2;

    select count(RecId) from metReqItemTable
        exists join reqItemTable
        where reqItemTable.RecId == metReqItemTable.RefRecId
        && metReqItemTable.SlotLoc1Area != ''
        exists join inventDim
        where inventDim.inventDimId == reqItemTable.CovInventDimId
        && inventDim.InventLocationId == _warehouse;

    noOfRecordsField.value(metReqItemTable.RecId);

    if (metReqItemTable.RecId > oneThousand && (metReqItemTable.RecId/oneThousand) > twelve)
    {
        threadCountField.value(twelve);
    }
    else if (metReqItemTable.RecId > oneThousand && (metReqItemTable.RecId/oneThousand) < twelve)
    {
        threadCountField.value(metReqItemTable.RecId/oneThousand);
    }
    else if (metReqItemTable.RecId < oneThousand )
    {
        threadCountField.value(two);
    }
}
